import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';

const Chat = () => {
  const location = useLocation();
  const { personality } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [error, setError] = useState(null);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    // 사용자의 메시지 추가
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "user", message: userInput },
    ]);

    // 입력창 비우기 (메시지 전송 직후)
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality }),
      });

      // if (!response.ok) {
      //   // 서버에서 반환된 에러를 읽어와서 처리
      //   const errorData = await response.json();
      //   throw new Error(errorData.detail || "챗봇 응답을 처리하는 중 오류가 발생했습니다.");
      // }

      const data = await response.json();
      const chatbotMessage = typeof data.response === "string"
        ? data.response
        : JSON.stringify(data.response);

      // 챗봇 응답을 chatHistory에 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: chatbotMessage },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);  // 서버에서 발생한 에러 메시지 표시

      // 욕설이 포함된 메시지가 있는 경우 경고창 띄우고 채팅 내용 삭제
      if (error.message.includes("욕설은 사용할 수 없습니다.")) {
        alert("부적절한 내용 사용할 수 없습니다. 메시지를 삭제합니다.");
        setChatHistory((prevHistory) => prevHistory.filter(chat => chat.message !== userInput));  // 채팅에서 욕설 메시지 삭제
        setUserInput("");  // 입력창 초기화
      }
    }
  };

  // 엔터 키를 눌렀을 때 메시지를 전송하도록 처리
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div>
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender}>
            <strong>{chat.sender === "user" ? "User" : "Chatbot"}:</strong> {chat.message}
          </div>
        ))}
      </div>
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}  // 엔터 키 입력 감지
        />
        <button onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
